const CHAVE_CADASTRO = "raizes-da-igualdade:cadastro"; function salvarCadastro(dados) { try { localStorage.setItem(CHAVE_CADASTRO, JSON.stringify(dados)); return true; } catch (erro) { console.error("NÃ£o foi possÃ­vel salvar o cadastro.", erro); return false; } } function recuperarCadastro() { try { const dados = localStorage.getItem(CHAVE_CADASTRO); return dados ? JSON.parse(dados) : null; } catch (erro) { console.error("NÃ£o foi possÃ­vel recuperar o cadastro.", erro); return null; } } window.armazenamentoCadastro = { salvarCadastro, recuperarCadastro };